// TC-042 | req_ids: REQ-009 | level: api | type: hybrid | model: shopcheck@25673b2
// Administrator deletes a user whose orders are all shipped or cancelled
// Generated by the QA spec generator (rung 2) — deterministic assembly; do not hand-edit.

import { test, expect } from '../../../fixtures';

test('TC-042: Administrator deletes a user whose orders are all shipped or cancelled', async ({ api, loginAs }) => {
  // reset_state is automatic (harness beforeEach)
  await loginAs('admin');
  await api.get('/api/users');
  // runtime pick: customer with no open (pending/paid) orders — delete-eligible (API contract)
  // NOTE: no seeded customer's orders are exclusively shipped/cancelled — a customer with no open
  // orders satisfies the same delete gate (refusal is on open orders only).
  const users: { id: number; username: string; role: string; is_locked: boolean }[] = await (await api.get('/api/users')).json();
  const orders: { id: number; user_id: number; status: string; items: { product_id: number; quantity: number; unit_price: number }[] }[] = await (await api.get('/api/orders')).json();
  const openOwnerIds = new Set(orders.filter((o) => o.status === 'pending' || o.status === 'paid').map((o) => o.user_id));
  const deletableUser = users.find((u) => u.role === 'customer' && !openOwnerIds.has(u.id));
  if (!deletableUser) throw new Error('seed has no customer without open (pending/paid) orders');
  // status expectation from verification step 4 — asserted on this call's own response
  const res = await api.delete(`/api/users/${deletableUser.id}`);
  expect(res.status()).toBe(204);
  await api.get('/api/users');
  // (204 is the preceding mutating call's status — asserted there, on its own response)
  // Expected: 204; account removed from list
});
